mkuse!{use std :: fmt ;}
mkitem!{mkenum!{# [derive (Clone , Copy , PartialEq)] pub enum Mode { NoSync , Sync , }}}
mkuse!{use std :: cell :: { Cell , UnsafeCell } ;}
mkuse!{use std :: intrinsics :: unlikely ;}
mkuse!{use std :: marker :: PhantomData ;}
mkuse!{use std :: mem :: ManuallyDrop ;}
mkuse!{use std :: ops :: { Deref , DerefMut } ;}
mkuse!{use parking_lot :: RawMutex ;}
mkuse!{use parking_lot :: lock_api :: RawMutex as _ ;}
mkuse!{use crate :: sync :: { DynSend , DynSync , mode } ;}
mkitem!{mkstruct!{# [doc = " A guard holding mutable access to a `Lock` which is in a locked state."] # [must_use = "if unused the Lock will immediately unlock"] pub struct LockGuard < 'a , T > { lock : & 'a Lock < T > , marker : PhantomData < & 'a mut T > , # [doc = " The synchronization mode of the lock. This is explicitly passed to let LLVM relate it"] # [doc = " to the original lock operation."] mode : Mode , }}}
mkitem!{mkimpl!{impl < 'a , T : 'a > Deref for LockGuard < 'a , T > { type Target = T ; # [inline] fn deref (& self) -> & T { unsafe { & * self . lock . data . get () } } }}}
mkitem!{mkimpl!{impl < 'a , T : 'a > DerefMut for LockGuard < 'a , T > { # [inline] fn deref_mut (& mut self) -> & mut T { unsafe { & mut * self . lock . data . get () } } }}}
mkitem!{mkimpl!{impl < 'a , T : 'a > Drop for LockGuard < 'a , T > { # [inline] fn drop (& mut self) { match self . mode { Mode :: NoSync => { let cell = unsafe { & self . lock . mode_union . no_sync } ; debug_assert ! (cell . get ()) ; cell . set (false) ; } Mode :: Sync => unsafe { self . lock . mode_union . sync . unlock () } , } } }}}
mkitem!{union ModeUnion { # [doc = " Indicates if the cell is locked. Only used if `Lock.mode` is `NoSync`."] no_sync : ManuallyDrop < Cell < bool > > , # [doc = " A lock implementation that's only used if `Lock.mode` is `Sync`."] sync : ManuallyDrop < RawMutex > , }}
mkitem!{# [doc = " The value representing a locked state for the `Cell`."] const LOCKED : bool = true ;}
mkitem!{mkstruct!{# [doc = " A lock which only uses synchronization if `might_be_dyn_thread_safe` is true."] # [doc = " It implements `DynSend` and `DynSync` instead of the typical `Send` and `Sync`."] pub struct Lock < T > { # [doc = " Indicates if synchronization is used via `mode_union.sync` if it's `Sync`, or if a"] # [doc = " not thread safe cell is used via `mode_union.no_sync` if it's `NoSync`."] # [doc = " This is set on initialization and never changed."] mode : Mode , mode_union : ModeUnion , data : UnsafeCell < T > , }}}
mkitem!{mkimpl!{impl < T > Lock < T > { # [inline (always)] pub fn new (inner : T) -> Self { let (mode , mode_union) = if unlikely (mode :: might_be_dyn_thread_safe ()) { (Mode :: Sync , ModeUnion { sync : ManuallyDrop :: new (RawMutex :: INIT) }) } else { (Mode :: NoSync , ModeUnion { no_sync : ManuallyDrop :: new (Cell :: new (! LOCKED)) }) } ; Lock { mode , mode_union , data : UnsafeCell :: new (inner) } } # [inline (always)] pub fn into_inner (self) -> T { self . data . into_inner () } # [inline (always)] pub fn get_mut (& mut self) -> & mut T { self . data . get_mut () } # [inline (always)] pub fn try_lock (& self) -> Option < LockGuard < '_ , T > > { let mode = self . mode ; match mode { Mode :: NoSync => { let cell = unsafe { & self . mode_union . no_sync } ; let was_unlocked = cell . get () != LOCKED ; if was_unlocked { cell . set (LOCKED) ; } was_unlocked } Mode :: Sync => unsafe { self . mode_union . sync . try_lock () } , } . then (| | LockGuard { lock : self , marker : PhantomData , mode }) } # [doc = " This acquires the lock assuming synchronization is in a specific mode."] # [doc = ""] # [doc = " Safety"] # [doc = " This method must only be called with `Mode::Sync` if `might_be_dyn_thread_safe` was"] # [doc = " true on lock creation."] # [inline (always)] # [track_caller] pub unsafe fn lock_assume (& self , mode : Mode) -> LockGuard < '_ , T > { # [inline (never)] # [track_caller] # [cold] fn lock_held () -> ! { panic ! ("lock was already held") } unsafe { match mode { Mode :: NoSync => { if unlikely (self . mode_union . no_sync . replace (LOCKED) == LOCKED) { lock_held () } } Mode :: Sync => self . mode_union . sync . lock () , } } LockGuard { lock : self , marker : PhantomData , mode } } # [inline (always)] # [track_caller] pub fn lock (& self) -> LockGuard < '_ , T > { unsafe { self . lock_assume (self . mode) } } }}}
mkitem!{mkimpl!{unsafe impl < T : DynSend > DynSend for Lock < T > { }}}
mkitem!{mkimpl!{unsafe impl < T : DynSend > DynSync for Lock < T > { }}}
mkitem!{mkimpl!{impl < T > Lock < T > { # [inline (always)] # [track_caller] pub fn with_lock < F : FnOnce (& mut T) -> R , R > (& self , f : F) -> R { f (& mut * self . lock ()) } # [inline (always)] # [track_caller] pub fn borrow (& self) -> LockGuard < '_ , T > { self . lock () } # [inline (always)] # [track_caller] pub fn borrow_mut (& self) -> LockGuard < '_ , T > { self . lock () } }}}
mkitem!{mkimpl!{impl < T : Default > Default for Lock < T > { # [inline] fn default () -> Self { Lock :: new (T :: default ()) } }}}
mkitem!{mkimpl!{impl < T : fmt :: Debug > fmt :: Debug for Lock < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match self . try_lock () { Some (guard) => f . debug_struct ("Lock") . field ("data" , & & * guard) . finish () , None => { struct LockedPlaceholder ; impl fmt :: Debug for LockedPlaceholder { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . write_str ("<locked>") } } f . debug_struct ("Lock") . field ("data" , & LockedPlaceholder) . finish () } } } }}}